function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 1000) return 'Each row needs 1 to 1000 cells.';
  if (grid.length * n > 100000) return 'grid can have at most 10^5 cells.';
  for (const row of grid) {
    if (row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every cell must be 0 or 1.';
  }
  if (grid[0][0] !== 1 || grid[grid.length - 1][n - 1] !== 1) return 'The top-left and bottom-right cells must be 1.';
  return null;
}

