function isPossibleToCutPath(grid) {
  const m = grid.length;
  const n = grid[0].length;

  function dfs(row, col) {
    if (row === m - 1 && col === n - 1) {
      return true;
    }
    if (row >= m || col >= n || grid[row][col] === 0) {
      return false;
    }
    grid[row][col] = 0;
    return dfs(row + 1, col) || dfs(row, col + 1);
  }

  if (!dfs(0, 0)) {
    return true;
  }
  grid[0][0] = 1;
  return !dfs(0, 0);
}

