function isPossibleToCutPath(grid) {
  const m = grid.length, n = grid[0].length;
  // Grid DP: can each cell be reached from (0, 0) by down/right steps over 1s?
  const connected = (cells) => {
    const reach = cells.map(row => row.map(() => false));
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        if (cells[r][c] !== 1) continue;
        reach[r][c] = (r === 0 && c === 0) || (r > 0 && reach[r - 1][c]) || (c > 0 && reach[r][c - 1]);
      }
    }
    return reach[m - 1][n - 1];
  };
  if (!connected(grid)) return true;
  // Try every allowed single flip.
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if ((r === 0 && c === 0) || (r === m - 1 && c === n - 1)) continue;
      const copy = grid.map(row => row.slice());
      copy[r][c] = 1 - copy[r][c];
      if (!connected(copy)) return true;
    }
  }
  return false;
}

