function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n;
  if (size === 'small') {
    m = pick(1, 6);
    n = pick(1, 6);
  } else {
    const thin = rand() < 0.15;
    m = thin ? pick(1, 3) : pick(60, 100);
    n = thin ? pick(60, 100) : pick(60, 100);
    if (rand() < 0.5) [m, n] = [n, m];
  }
  const shape = rand();
  const density = shape < 0.4 ? 0.85 + rand() * 0.15 : shape < 0.7 ? 0.6 + rand() * 0.3 : 0.97;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  // Sometimes leave a single open cell on one anti-diagonal, which every walk must pass through.
  if (shape >= 0.7 && m + n > 3) {
    const diagonal = pick(1, m + n - 3);
    const cells = [];
    for (let r = 0; r < m; r++) {
      const c = diagonal - r;
      if (c >= 0 && c < n) cells.push([r, c]);
    }
    const keep = cells[Math.floor(rand() * cells.length)];
    for (const [r, c] of cells) grid[r][c] = r === keep[0] && c === keep[1] ? 1 : 0;
    if (rand() < 0.5) {
      const [r, c] = cells[Math.floor(rand() * cells.length)];
      grid[r][c] = 1;
    }
  }
  grid[0][0] = 1;
  grid[m - 1][n - 1] = 1;
  return [grid];
}
